// T-AC-03: unknown effects require reconciliation; terminal operations cannot restart.
describe("effect uncertainty and terminal operation guards", () => {
  it("T37 requires reconciliation before an unknown operation may finish or execute again", () => {
    for (const target of ["queued", "running", "succeeded", "cancelled"] as const) {
      expect(() => assertTransition("unknown", target)).toThrow();
    }
    expect(() => assertTransition("unknown", "reconciling")).not.toThrow();
  });

  it.each(["succeeded", "failed", "cancelled"] as const)(
    "T37 never silently restarts a terminal %s operation",
    (terminal) => {
      for (const target of ["queued", "running", "reconciling"] satisfies OperationState[]) {
        expect(() => assertTransition(terminal, target)).toThrow();
      }
    },
  );
});

// T-AC-03: verify the local audit chain and detect record/link corruption.
describe("local audit integrity", () => {
  let store: Store;
  let core: ControlPlane;

  beforeEach(async () => {
    store = await openStore();
    core = new ControlPlane(store);
  });

  afterEach(async () => {
    await store.close();
  });

  it("T37 preserves a verifiable chain when independent writes arrive concurrently", async () => {
    await Promise.all(
      Array.from({ length: 5 }, (_, index) =>
        core.createProject(
          owner,
          { ...projectInput, slug: `audit-project-${index}` },
          randomUUID(),
        ),
      ),
    );

    expect(await core.listAudit(owner)).toHaveLength(5);
    expect(await verifyAudit(store)).toBe(true);
  });

  it("T37 detects a modified audit summary against its stored digest", async () => {
    await core.createProject(owner, projectInput, randomUUID());

    await store.db.execute("UPDATE audit SET summary = 'altered fixture summary'");

    expect(await verifyAudit(store)).toBe(false);
  });

  it("T37 detects a chain link replaced with an unrelated predecessor", async () => {
    await core.createProject(owner, projectInput, randomUUID());
    const [record] = await store.db.select().from(schema.audit);
    if (!record) throw new Error("Audit fixture was not created");
    const { sequence: _sequence, hash: _hash, ...entry } = record;
    const forged = {
      ...entry,
      previousHash: "unrelated-fixture-predecessor",
      occurredAt: entry.occurredAt.toISOString(),
    };
    // Keep this record's digest valid: only the predecessor relationship is broken.
    const canonicalEntry = Object.fromEntries(
      Object.entries(forged).sort(([left], [right]) => left.localeCompare(right)),
    );
    const hash = createHash("sha256").update(JSON.stringify(canonicalEntry)).digest("hex");

    await store.db.update(schema.audit).set({ previousHash: forged.previousHash, hash });

    expect(await verifyAudit(store)).toBe(false);
  });

  // T-AC-04: one signed delivery creates one pending CI intent per matching project.
  it("T41 fans out a matching push to every bound monorepo project exactly once", async () => {
    for (const slug of ["monorepo-web", "monorepo-api"]) {
      const project = await core.createProject(owner, { ...projectInput, slug }, randomUUID());
      await core.configureRepository(owner, project.id, repository, project.revision, randomUUID());
    }
    const delivery = signedDelivery();

    await core.receiveGithubDelivery(delivery, webhookKey);
    await core.receiveGithubDelivery(delivery, webhookKey);

    const runs = await core.listCiRuns(owner);
    expect(runs).toHaveLength(2);
    expect(new Set(runs.map((run) => run.projectId)).size).toBe(2);
    expect(runs.every((run) => run.status === "pending_verification")).toBe(true);
  });
});

// T-AC-02: request replay remains idempotent after local storage restarts.
describe("durable idempotency journal", () => {
  it("T09 replays a creation key after reopening storage without creating another resource", async () => {
    const dataDir = await mkdtemp(join(tmpdir(), "godseye-replay-"));
    const key = randomUUID();
    let store: Store | undefined;
    try {
      store = await openStore({ dataDir });
      let core = new ControlPlane(store);
      const first = await core.createProject(owner, projectInput, key);

      await store.close();
      store = undefined;
      store = await openStore({ dataDir });
      core = new ControlPlane(store);
      const replay = await core.createProject(owner, projectInput, key);

      expect(replay.id).toBe(first.id);
      expect(await core.listProjects(owner)).toHaveLength(1);
      expect(await core.listAudit(owner)).toHaveLength(1);
      await expect(
        core.createProject(owner, { ...projectInput, name: "Changed after restart" }, key),
      ).rejects.toMatchObject({ code: "IDEMPOTENCY_CONFLICT", status: 409 });
    } finally {
      await store?.close();
      await rm(dataDir, { recursive: true, force: true });
    }
  });
});
